python3 -c "
import workcell
# Try some commands
for cmd in ['unbolt', 'unclamp', 'loosen', 'release_clamp', 'remove_clamp', 'adjust_clamp', 'rotate_clamp', 'clamp']:
    r = workcell.call('robot', cmd, 'C2')
    if r.ok:
        print(f'{cmd}: {r.text}')
    else:
        print(f'{cmd}: FAILED - {r.text}')
"

